(276, 'Larkdale Elementary', '0621', 1, 'Only Elementary School in Broward County with a Culinary Program -	Expanding innovative learning opportunities through the development of a Culinary Garden & Teaching Kitchen program funded by a $500,000 grant from the Emeril Lagasse Foundation. -	This initiative integrates science, wellness, gardening, and culinary experiences into student learning.', '2026-05-07 17:58:00-04', '2026-05-08'),
(276, 'Larkdale Elementary', '0621', 2, 'Thriving school garden  -Provides fresh vegetables, herbs, and teas used within our culinary program, allowing students to experience hands-on learning from garden to table while developing knowledge of nutrition, sustainability, and healthy living.', '2026-05-07 17:58:00-04', '2026-05-08'),
(276, 'Larkdale Elementary', '0621', 3, 'Strong Community Ties  - Free afterschool tutoring afterschool daily.  -Buy-in from organizations, local leaders, volunteers, and businesses to support tutoring, mentoring, incentives, beautification projects, and student enrichment opportunities.', '2026-05-07 17:58:00-04', '2026-05-08'),
(276, 'Larkdale Elementary', '0621', 4, 'Utilizing data-driven instructional practices  -FAST PM monitoring, Common Formative Assessments  -i-Ready implementation  -targeted reteaching and enrichment strategies to support academic growth and student achievement.', '2026-05-07 17:58:00-04', '2026-05-08'),
(276, 'Larkdale Elementary', '0621', 5, 'Promoting leadership and character development   -Leader in Me, collaborative student activities, and opportunities that encourage responsibility, teamwork, and confidence.', '2026-05-07 17:58:00-04', '2026-05-08'),
(277, 'McNicol Middle Magnet & STEM', '0481', 1, 'Recognized Magnet School of Excellence: McNicol Magnet & STEM Middle School earned the Magnet Schools of America Merit School of Excellence Award, recognizing the school’s strong magnet programming, academic growth, and student engagement across content areas.', '2026-05-11 11:53:00-04', '2026-05-12'),
(277, 'McNicol Middle Magnet & STEM', '0481', 2, 'Science & Pre-Engineering Innovation Excellence:  McNicol’s D1 Mighty Hawks Drone Team designs, builds, codes, and pilots high-speed racing drones while competing in aviation and engineering challenges. The team has advanced to championship-level competitions beyond the district level, showcasing innovation, teamwork, and real-world STEM application.', '2026-05-11 11:53:00-04', '2026-05-12'),
(277, 'McNicol Middle Magnet & STEM', '0481', 3, 'STEM Innovation: McNicol’s STEM Magnet Program provides students with rigorous, hands-on learning experiences in science, technology, engineering, and mathematics through project?based learning, advanced coursework, and real?world problem solving. Students engage in authentic tasks that build critical thinking, collaboration, and college? and career?ready skills aligned to high?demand STEM pathways.', '2026-05-11 11:53:00-04', '2026-05-12'),
(278, 'McNicol Middle Magnet & STEM', '0481', 2, 'Science & Pre-Engineering Innovation Excellence: McNicol’s D1 Mighty Hawks Drone Team designs, builds, codes, and pilots high-speed racing drones while competing in aviation and engineering challenges. The team earned the Diamond Award at the State Championship and advanced to championship-level competitions beyond the district level, showcasing innovation, teamwork, and real-world STEM application.', '2026-05-11 12:10:00-04', '2026-05-12'),
(279, 'Broward Estates Elementary', '0501', 1, 'Broward Estates Early Learning & Resource Center proudly serves scholars from birth through age five, providing a strong foundation during the most important years of development.', '2026-05-11 16:03:00-04', '2026-05-12'),
(279, 'Broward Estates Elementary', '0501', 2, 'We are the only early learning and resource center in Central Broward offering the unique combination of educational programs for children and adults and family resources available on our campus.', '2026-05-11 16:03:00-04', '2026-05-12'),
